tool_input.command:
T=$(mktemp -d) && mkdir -p $T/services/api/src && printf "import Anthropic from '@anthropic-ai/sdk';
import type {
  Message,
} from '@anthropic-ai/sdk/resources';
" > $T/services/api/src/claude.mts && printf "export { ChatOpenAI } from '@langchain/openai';
// import mock from 'openai-mock'
" > $T/services/api/src/chain.cts && cd $T && node /private/tmp/100-tricks-runs/pilot-hard/without/h4-scan-llm-sdks/r2/packages/frai-cli/dist/index.js scan services/api --json && node /private/tmp/100-tricks-runs/pilot-hard/without/h4-scan-llm-sdks/r2/packages/frai-cli/dist/index.js scan && cd /private/tmp/100-tricks-runs/pilot-hard/without/h4-scan-llm-sdks/r2/packages/frai-agent && node --input-type=module -e "
import { scanRepositoryTool } from './dist/tools/scan-tool.js';
console.log(await scanRepositoryTool.func({ root: '$T' }));
console.log(await scanRepositoryTool.func({ root: '../../examples/support-triage-demo' }));
console.log(await scanRepositoryTool.func({ root: '$T/missing' }));
"

rm -rf /tmp/frai-llm-check && mkdir -p /tmp/frai-llm-check/services/api/src && printf "import Anthropic from '@anthropic-ai/sdk';
import type {
  Message,
} from '@anthropic-ai/sdk/resources';
" > /tmp/frai-llm-check/services/api/src/claude.mts && printf "export { ChatOpenAI } from '@langchain/openai';
// import mock from 'openai-mock'
" > /tmp/frai-llm-check/services/api/src/chain.cts

cd /private/tmp/100-tricks-runs/pilot-hard/without/h4-scan-llm-sdks/r2 && for f in README.md packages/frai-cli/README.md; do node -e "
const fs=require('fs');const f='$f';let s=fs.readFileSync(f,'utf8');
s=s.replace('| \`frai scan [--ci] [--json]\` | Scan the repository for AI/ML indicators. |','| \`frai scan [directory] [--ci] [--json]\` | Scan the repository (or a directory) for AI/ML and LLM SDK indicators. |');
s=s.replace('Scans the repository for AI-related libraries, functions, and files. Use \`--ci\` for non-interactive mode or \`--json\` to emit raw JSON.','Scans the repository for AI-related libraries (including LLM SDKs such as \`openai\`, \`anthropic\`, \`@anthropic-ai/sdk\`, \`langchain\` and \`@langchain/*\`), functions, and files. Pass a directory to scan only that path (\`frai scan services/api\`); a missing directory fails with a non-zero exit. Use \`--ci\` for non-interactive mode or \`--json\` to emit raw JSON.');
fs.writeFileSync(f,s);"; done; git diff --stat -- README.md packages/frai-cli/README.md; npx eslint packages/frai-core/src/scanners 2>&1 | tail -15
